############### New triple
{
  cmw:securityContext cmw:currentUser ?currentUser.
    ?role role:roleMembers ?currentUser. 
    ?task task:objectId ?item.
    ?task cmw:taskStatus taskStatus:inProgress.

    or {?task cmw:assignee ?currentUser.}
    or {?task cmw:possibleAssignee ?currentUser.}
    or {?task cmw:assignee ?role.}
  or {?task cmw:possibleAssignee ?role.}.

    ?task cmw:title ?value.

}
